(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-965":{scenario:{company:"Voltana Storage Systems",supervisor:{name:"Kiều Thanh Nhàn",role:{vi:"Trưởng phòng Kỹ thuật BESS",en:"BESS Engineering Manager"}},ref_code:"CF-3318",title:{vi:"Đúng hóa học cell. Đúng kWh giao lưới.",en:"Right cell chemistry. Right kWh to grid."},brief:{vi:"Bạn rà soát cấu hình nghiệm thu CF-3318 của hệ BESS-2 (2500 kWh DC) tại một nhà máy điện mặt trời. Datasheet cell ghi 3.2 V danh định, 280 Ah; cửa sổ SOC vận hành 10-90%; thử dung lượng tháng 9 cho SOH 95%; hiệu suất xả một chiều PCS và biến áp 95%. Sửa hồ sơ hóa học cell trong BMS và năng lượng xả khả dụng tại điểm đấu nối (POI) trên bản nháp, rồi lập báo cáo có căn cứ (số liệu mô phỏng).",en:"You are reviewing commissioning configuration CF-3318 for BESS-2 (2500 kWh DC) at a solar plant. The cell datasheet shows 3.2 V nominal, 280 Ah; the operating SOC window is 10-90%; the September capacity test gave SOH 95%; one-way PCS and transformer discharge efficiency is 95%. Correct the BMS cell chemistry profile and the usable discharge energy at the point of interconnection (POI) in the draft, then write an evidence-based report (simulated data)."},reference_title:{vi:"Hồ sơ thiết kế & thử nghiệm đã duyệt · CF-3318",en:"Approved design & test file · CF-3318"},fields:[{id:"CELL_CHEM",label:{vi:"Hồ sơ hóa học cell trong BMS",en:"BMS cell chemistry profile"},initial:"NMC",expected:"LFP",choices:["NMC","LFP","LTO"],reference:"Datasheet cell và hồ sơ BMS",hint:{vi:"Điện áp danh định 3.2 V và ngưỡng nạp 3.65 V/cell khác hẳn mức 3.6-3.7 V danh định của NMC hay 2.3-2.4 V của LTO.",en:"A 3.2 V nominal cell with a 3.65 V charge limit is far from NMC at 3.6-3.7 V nominal or LTO at 2.3-2.4 V."}},{id:"USABLE_KWH",label:{vi:"Năng lượng xả khả dụng tại POI (kWh)",en:"Usable discharge energy at POI (kWh)"},initial:"2000",expected:"1805",reference:"Bảng tính năng lượng khả dụng",ref_value:{vi:"Danh định 2500 kWh DC; SOC 10-90%; SOH 95%; hiệu suất xả PCS + biến áp 95%",en:"Nameplate 2500 kWh DC; SOC 10-90%; SOH 95%; PCS + transformer discharge efficiency 95%"},hint:{vi:"Năng lượng tại điểm đấu nối phải trừ cả suy giảm dung lượng và tổn hao chuyển đổi, không chỉ cửa sổ SOC.",en:"Energy at the interconnection point must account for capacity fade and conversion losses, not just the SOC window."}}],sop32:{vi:"Năng lượng xả khả dụng tại POI (kWh) = dung lượng danh định DC x (SOCmax - SOCmin) x SOH x hiệu suất xả một chiều của PCS và biến áp.",en:"Usable discharge energy at POI (kWh) = DC nameplate capacity x (SOCmax - SOCmin) x SOH x one-way discharge efficiency of the PCS and transformer."},context:{label:"EMS / CF-3318",metrics:[{label:{vi:"Dung lượng danh định DC",en:"DC nameplate capacity"},value:"2,500 kWh"},{label:{vi:"Cửa sổ SOC",en:"SOC window"},value:"10-90%"},{label:{vi:"SOH thử tháng 9",en:"September test SOH"},value:"95%"},{label:{vi:"Hiệu suất xả PCS + biến áp",en:"PCS + transformer efficiency"},value:"95%"}]},crisis:{vi:"Quản lý dự án EPC nhắn: “Cứ để hồ sơ NMC, tắt tạm cảnh báo quá áp cell để chạy thử 72 giờ cho kịp ngày vận hành thương mại, xong rồi chỉnh sau. Chủ đầu tư phạt chậm tiến độ từng ngày đấy.”",en:"The EPC project manager messages you: “Leave the NMC profile, mute the cell overvoltage alarm and run the 72-hour test to hit the commercial operation date, we will fix it later. The owner charges delay penalties every day.”"},options:{safe:{vi:"Dừng nạp, nạp đúng hồ sơ LFP với ngưỡng 3.65 V/cell, giữ mọi liên động bảo vệ và báo giám đốc dự án cùng bộ phận an toàn; chạy thử lại sau khi kiểm tra rack R3.",en:"Stop charging, load the correct LFP profile with a 3.65 V/cell limit, keep every protection interlock and inform the project director and safety team; retest after inspecting rack R3."},shortcut:{vi:"Tắt cảnh báo quá áp để chạy đủ 72 giờ, sửa hồ sơ BMS sau ngày vận hành thương mại.",en:"Mute the overvoltage alarm to finish the 72 hours and fix the BMS profile after the commercial operation date."},wait:{vi:"Để hệ thống tiếp tục chạy thử và chờ nhà cung cấp BMS sang kiểm tra vào tuần sau.",en:"Let the test continue and wait for the BMS vendor to visit next week."}},questions:{vi:["Dữ liệu nào cho thấy cell là LFP, và hồ sơ NMC gây rủi ro gì cho ngưỡng nạp của BMS?","Trình bày cách tính năng lượng khả dụng tại POI và hậu quả nếu cam kết với bên mua điện theo con số 2000 kWh."],en:["Which data shows the cells are LFP, and what risk does the NMC profile create for the BMS charge limits?","Explain how you calculated usable energy at the POI and the consequence of committing 2000 kWh to the offtaker."]},hints:{vi:["Đọc thông tin rack và tệp cấu hình BMS, so điện áp danh định với ngưỡng đang cài.","Áp dụng đủ bốn thừa số ở SOP mục 3.2: dung lượng, cửa sổ SOC, SOH và hiệu suất xả.","Đọc lại SOP mục 4.2: không tắt hay bỏ qua bảo vệ pin để chạy kịp tiến độ; báo cáo người có thẩm quyền."],en:["Read the rack information and BMS config file, then compare nominal voltage with the configured limit.","Apply all four factors in SOP 3.2: capacity, SOC window, SOH and discharge efficiency.","Re-read SOP 4.2: never mute or bypass battery protection to meet a schedule; escalate to the responsible authority."]},terminal:{system:"bess-ems",settable:["CELL_CHEM","USABLE_KWH"],commands:[{cmd:"bms info",out:{vi:"Rack R1-R8: cell lăng trụ 3.2 V danh định, 280 Ah; dải làm việc của nhà sản xuất 2.5-3.65 V/cell.",en:"Racks R1-R8: prismatic cells 3.2 V nominal, 280 Ah; manufacturer operating range 2.5-3.65 V/cell."}},{cmd:"cat bms.cfg",out:{vi:"Tệp cấu hình hiện tại: chem_profile=NMC; v_cell_max=4.20; v_cell_min=3.00; soc_max=90; soc_min=10",en:"Current config file: chem_profile=NMC; v_cell_max=4.20; v_cell_min=3.00; soc_max=90; soc_min=10"}},{cmd:"alarm log",out:{vi:"Cảnh báo: cell R3-M07-C12 đạt 3.71 V khi nạp, BMS chưa ngắt vì ngưỡng đang cài là 4.20 V.",en:"Warning: cell R3-M07-C12 reached 3.71 V while charging; the BMS did not trip because the limit is set at 4.20 V."}},{cmd:"soh report",out:{vi:"Thử dung lượng 15/09/2026 ở 0.5C: SOH trung bình 95%, lệch giữa các rack 1.2%.",en:"Capacity test 15/09/2026 at 0.5C: average SOH 95%, rack-to-rack spread 1.2%."}},{cmd:"pcs status",out:{vi:"PCS 1000 kW; hiệu suất xả một chiều PCS + biến áp đo được 95% tại 75% tải; dung lượng danh định DC 2500 kWh.",en:"PCS 1000 kW; measured one-way PCS + transformer discharge efficiency 95% at 75% load; DC nameplate 2500 kWh."}}]}},learning:{summary:{vi:"Kỹ sư hệ thống lưu trữ năng lượng thiết kế, tích hợp, nghiệm thu và vận hành hệ BESS gồm cell, BMS, PCS, EMS và hệ thống an toàn cháy. Nghề này biến pin thành nguồn linh hoạt cho cắt đỉnh, dịch chuyển năng lượng tái tạo và điều tần, đòi hỏi hiểu điện hóa, điện tử công suất, đấu nối lưới và kỷ luật an toàn với rủi ro thoát nhiệt.",en:"A battery energy storage systems engineer designs, integrates, commissions and operates BESS made of cells, BMS, PCS, EMS and fire safety systems. The role turns batteries into a flexible resource for peak shaving, renewable shifting and frequency response, and requires electrochemistry, power electronics, grid connection and strict safety discipline around thermal runaway."},responsibilities:{vi:["Định cỡ hệ BESS theo bài toán sử dụng: công suất, năng lượng, C-rate, tuổi thọ và suy giảm.","Kiểm tra thiết kế tích hợp cell, rack, BMS, PCS, biến áp và hệ thống phòng cháy, thông gió.","Lập và thực hiện quy trình nghiệm thu: thử dung lượng, hiệu suất khứ hồi, bảo vệ và đáp ứng lưới.","Giám sát vận hành qua EMS: SOC, SOH, nhiệt độ, lệch áp cell và cảnh báo an toàn.","Theo dõi bảo hành, phân tích suy giảm và đề xuất chiến lược vận hành kéo dài tuổi thọ."],en:["Size the BESS to the use case: power, energy, C-rate, lifetime and degradation.","Review the integration of cells, racks, BMS, PCS, transformer, fire protection and ventilation.","Write and run commissioning tests: capacity, round-trip efficiency, protection and grid response.","Monitor operation through the EMS: SOC, SOH, temperature, cell imbalance and safety alarms.","Track warranties, analyze degradation and propose operating strategies that extend life."]},competencies:[{name:{vi:"Điện hóa pin",en:"Battery electrochemistry"},desc:{vi:"Hiểu đặc tính LFP, NMC, LTO: điện áp, mật độ năng lượng, tuổi thọ chu kỳ và ngưỡng thoát nhiệt.",en:"Understand LFP, NMC and LTO: voltage, energy density, cycle life and thermal runaway thresholds."}},{name:{vi:"Điện tử công suất & lưới",en:"Power electronics & grid"},desc:{vi:"Cấu hình PCS, bảo vệ, chất lượng điện năng và yêu cầu đấu nối của đơn vị vận hành lưới.",en:"Configure the PCS, protection, power quality and grid operator connection requirements."}},{name:{vi:"Định cỡ & mô hình hóa",en:"Sizing & modeling"},desc:{vi:"Mô phỏng lịch nạp xả, suy giảm theo chu kỳ và theo lịch, tính năng lượng khả dụng thực.",en:"Simulate charge and discharge schedules, cycle and calendar fade, and real usable energy."}},{name:{vi:"An toàn hệ thống pin",en:"Battery safety"},desc:{vi:"Giữ nguyên liên động bảo vệ, phát hiện sớm bất thường nhiệt và phối hợp phương án chữa cháy.",en:"Keep protection interlocks intact, detect thermal anomalies early and coordinate fire response."}},{name:{vi:"Nghiệm thu & tài liệu",en:"Commissioning & documentation"},desc:{vi:"Lập quy trình thử, ghi nhận kết quả trung thực và quản lý hồ sơ cấu hình.",en:"Write test procedures, record results honestly and control configuration records."}}],knowledge:{vi:["IEC 62619 về yêu cầu an toàn cho cell và pin lithium thứ cấp dùng trong công nghiệp.","Bộ IEC 62933 về hệ thống lưu trữ năng lượng điện: thuật ngữ, thông số, thử nghiệm và an toàn.","UL 9540 về an toàn hệ lưu trữ năng lượng và UL 9540A về phương pháp thử lan truyền thoát nhiệt.","NFPA 855 về lắp đặt hệ thống lưu trữ năng lượng tĩnh: khoảng cách, phát hiện khí, chữa cháy.","Luật Điện lực số 61/2024/QH15 và yêu cầu đấu nối, vận hành của hệ thống điện."],en:["IEC 62619 safety requirements for secondary lithium cells and batteries for industrial use.","The IEC 62933 series on electrical energy storage systems: terms, parameters, testing and safety.","UL 9540 for energy storage system safety and UL 9540A test method for thermal runaway propagation.","NFPA 855 on stationary energy storage installation: spacing, gas detection and fire suppression.","Electricity Law No. 61/2024/QH15 and power system connection and operation requirements."]},tools:["Phần mềm EMS/SCADA","Giao diện BMS và nhật ký cell","Máy phân tích chất lượng điện","Camera nhiệt","Bộ thử dung lượng và tải giả","Phần mềm mô phỏng định cỡ BESS"],kpis:{vi:["Hệ số khả dụng của hệ BESS (%).","Hiệu suất khứ hồi thực tế so với thiết kế.","Tốc độ suy giảm SOH mỗi năm so với cam kết bảo hành.","Số cảnh báo nhiệt, quá áp chưa xử lý quá hạn (mục tiêu bằng 0)."],en:["BESS availability factor (%).","Actual versus design round-trip efficiency.","Annual SOH fade versus the warranty commitment.","Overdue thermal and overvoltage alarms (target zero)."]},day:[{time:"07:30",vi:"Đọc báo cáo đêm: SOC, nhiệt độ rack, lệch áp cell và các cảnh báo EMS.",en:"Read the overnight report: SOC, rack temperatures, cell imbalance and EMS alarms."},{time:"09:00",vi:"Kiểm tra hiện trường container: thông gió, cảm biến khí, hệ thống chữa cháy.",en:"Inspect the containers: ventilation, gas sensors and fire suppression."},{time:"11:00",vi:"Lập lịch nạp xả ngày mai theo dự báo bức xạ và khung giờ cao điểm.",en:"Plan tomorrow's charge and discharge schedule from irradiance forecasts and peak hours."},{time:"14:00",vi:"Chạy một bước thử nghiệm thu, đối chiếu kết quả với tiêu chí hợp đồng.",en:"Run a commissioning test step and compare results with contract criteria."},{time:"16:30",vi:"Cập nhật hồ sơ cấu hình BMS, nhật ký sự cố và báo cáo cho chủ đầu tư.",en:"Update the BMS configuration record, incident log and the owner's report."}],mistakes:{vi:["Cam kết năng lượng theo dung lượng danh định DC mà quên SOC, SOH và tổn hao chuyển đổi.","Nạp hồ sơ hóa học cell sai, khiến ngưỡng điện áp và nhiệt độ bảo vệ không phù hợp.","Tắt hoặc bỏ qua cảnh báo bảo vệ để chạy thử kịp tiến độ."],en:["Committing energy based on DC nameplate while ignoring SOC, SOH and conversion losses.","Loading the wrong cell chemistry profile so voltage and temperature limits no longer fit.","Muting or bypassing protection alarms to finish tests on schedule."]},career:[{vi:"Kỹ thuật viên vận hành BESS",en:"BESS operations technician"},{vi:"Kỹ sư hệ thống lưu trữ năng lượng",en:"Energy storage systems engineer"},{vi:"Kỹ sư trưởng tích hợp và nghiệm thu BESS",en:"Lead BESS integration and commissioning engineer"},{vi:"Giám đốc kỹ thuật dự án lưu trữ năng lượng",en:"Energy storage technical director"}],glossary:[{term:"SOC",vi:"Trạng thái nạp: phần trăm năng lượng còn lại so với dung lượng hiện có của pin.",en:"State of charge: the remaining energy as a percentage of current capacity."},{term:"SOH",vi:"Trạng thái sức khỏe: dung lượng hiện tại so với dung lượng danh định ban đầu.",en:"State of health: current capacity relative to the original nameplate capacity."},{term:"C-rate",vi:"Tỷ lệ công suất nạp xả so với dung lượng; 0.5C nghĩa là xả hết trong khoảng 2 giờ.",en:"Charge or discharge power relative to capacity; 0.5C means a full discharge in about 2 hours."},{term:"PCS",vi:"Hệ thống chuyển đổi công suất, nghịch lưu hai chiều giữa pin DC và lưới AC.",en:"Power conversion system, the bidirectional inverter between the DC battery and the AC grid."},{term:"Thermal runaway",vi:"Thoát nhiệt: phản ứng tỏa nhiệt tự gia tốc trong cell, có thể lan sang cell khác và gây cháy.",en:"A self-accelerating exothermic reaction in a cell that can spread to others and cause fire."}],quiz:[{q:{vi:"Hệ 1000 kWh DC, SOC 10-90%, SOH 90%, hiệu suất xả 95%. Năng lượng khả dụng tại POI là bao nhiêu?",en:"A 1000 kWh DC system, SOC 10-90%, SOH 90%, discharge efficiency 95%. What is the usable energy at the POI?"},options:{vi:["800 kWh","720 kWh","950 kWh","684 kWh"],en:["800 kWh","720 kWh","950 kWh","684 kWh"]},answer:3,explain:{vi:"Năng lượng khả dụng = 1000 x 0.8 x 0.9 x 0.95 = 684 kWh.",en:"Usable energy = 1000 x 0.8 x 0.9 x 0.95 = 684 kWh."}},{q:{vi:"Cell có điện áp danh định 3.2 V, ngưỡng nạp 3.65 V thường thuộc họ hóa học nào?",en:"A cell with 3.2 V nominal and a 3.65 V charge limit usually belongs to which chemistry?"},options:{vi:["NMC","LFP","LTO","Chì axit"],en:["NMC","LFP","LTO","Lead acid"]},answer:1,explain:{vi:"LFP có điện áp danh định khoảng 3.2 V; NMC khoảng 3.6-3.7 V và LTO khoảng 2.3-2.4 V.",en:"LFP is about 3.2 V nominal; NMC is about 3.6-3.7 V and LTO about 2.3-2.4 V."}},{q:{vi:"Hệ 2000 kWh xả ở công suất 1000 kW. C-rate xả là bao nhiêu?",en:"A 2000 kWh system discharges at 1000 kW. What is the discharge C-rate?"},options:{vi:["2C","1C","0.5C","0.25C"],en:["2C","1C","0.5C","0.25C"]},answer:2,explain:{vi:"C-rate = 1000 kW / 2000 kWh = 0.5C, tức xả hết trong khoảng 2 giờ.",en:"C-rate = 1000 kW / 2000 kWh = 0.5C, a full discharge in about 2 hours."}},{q:{vi:"Nhà thầu đề nghị tắt cảnh báo quá áp cell để chạy thử kịp tiến độ. Bạn làm gì?",en:"The contractor asks you to mute the cell overvoltage alarm to finish testing on time. What do you do?"},options:{vi:["Từ chối, dừng nạp, sửa cấu hình đúng và báo người có thẩm quyền","Tắt cảnh báo nhưng cử người theo dõi","Giảm công suất nạp rồi tắt cảnh báo","Chờ nhà cung cấp quyết định"],en:["Refuse, stop charging, fix the configuration and escalate","Mute it but assign someone to watch","Reduce charging power and mute it","Let the vendor decide"]},answer:0,explain:{vi:"Bảo vệ quá áp ngăn thoát nhiệt; không được vô hiệu hóa để chạy tiến độ.",en:"Overvoltage protection prevents thermal runaway; it must never be disabled for schedule reasons."}}],tools_en:["EMS/SCADA software","BMS interface and cell logs","Power quality analyzer","Thermal camera","Capacity tester and load bank","BESS sizing simulation software"]}}})})(window.KKR);
